-- BANKING ANALYSIS

CREATE DATABASE IF NOT EXISTS banking_practice;
USE banking_practice;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS transactions;
DROP TABLE IF EXISTS loans;
DROP TABLE IF EXISTS accounts;
DROP TABLE IF EXISTS employees;
DROP TABLE IF EXISTS branches;
DROP TABLE IF EXISTS customers;
SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE customers(customer_id INT PRIMARY KEY, first_name VARCHAR(40) NOT NULL, last_name VARCHAR(40) NOT NULL, city VARCHAR(50) NOT NULL, age INT NOT NULL, occupation VARCHAR(60), join_date DATE NOT NULL);
CREATE TABLE branches(branch_id INT PRIMARY KEY, branch_name VARCHAR(80) NOT NULL, city VARCHAR(50) NOT NULL, manager_name VARCHAR(80));
CREATE TABLE employees(employee_id INT PRIMARY KEY, employee_name VARCHAR(80) NOT NULL, branch_id INT NOT NULL, job_title VARCHAR(50), salary DECIMAL(10,2), FOREIGN KEY(branch_id) REFERENCES branches(branch_id));
CREATE TABLE accounts(account_id INT PRIMARY KEY, customer_id INT NOT NULL, branch_id INT NOT NULL, account_type VARCHAR(30) NOT NULL, opened_date DATE NOT NULL, balance DECIMAL(12,2) NOT NULL, status VARCHAR(20) NOT NULL, FOREIGN KEY(customer_id) REFERENCES customers(customer_id), FOREIGN KEY(branch_id) REFERENCES branches(branch_id));
CREATE TABLE loans(loan_id INT PRIMARY KEY, customer_id INT NOT NULL, branch_id INT NOT NULL, loan_type VARCHAR(30) NOT NULL, loan_amount DECIMAL(12,2) NOT NULL, interest_rate DECIMAL(5,2) NOT NULL, loan_status VARCHAR(20) NOT NULL, issue_date DATE NOT NULL, FOREIGN KEY(customer_id) REFERENCES customers(customer_id), FOREIGN KEY(branch_id) REFERENCES branches(branch_id));
CREATE TABLE transactions(transaction_id INT PRIMARY KEY, account_id INT NOT NULL, transaction_date DATE NOT NULL, transaction_type VARCHAR(20) NOT NULL, amount DECIMAL(12,2) NOT NULL, channel VARCHAR(20) NOT NULL, FOREIGN KEY(account_id) REFERENCES accounts(account_id));

