-- View 10 transactions 
select * from transactions 
limit 10;

-- Find Chennai customers, oldest first 
select * from customers 
where city='Chennai' 
order by age desc;

-- Find the 20 highest-balance accounts above ₹100,000 
select * from accounts 
where balance > 100000 
order by balance desc limit 20;

-- Count customers in each city 
select city, count(*) as customer_count from customers 
group by city 
order by customer_count desc;

-- Count accounts and calculate average balance by account type 
select account_type, count(*) as account_count, round(avg(balance),2) as avg_balance from accounts 
group by account_type;

-- Find branches with more than ₹10 million in account balances 
select branch_id, sum(balance) as branch_total from accounts 
group by branch_id 
having sum(balance)>10000000 
order by branch_total desc;

--  Display customers and their accounts
select c.customer_id, concat(c.first_name,' ',c.last_name) as customer_name, a.account_id, a.account_type, a.balance from customers c 
join accounts a on c.customer_id=a.customer_id 
limit 25;

-- Calculate loan count and total loan amount by city
select c.city, count(l.loan_id) as loan_count, sum(l.loan_amount) as total_loans from customers c 
left join loans l on c.customer_id=l.customer_id 
group by c.city 
order by total_loans desc;

-- Display transaction details with customer and branch information 
select t.transaction_id, concat(c.first_name,' ',c.last_name) as customer_name, b.branch_name, t.transaction_date, t.transaction_type, t.amount from transactions t 
join accounts a on t.account_id=a.account_id 
join customers c on a.customer_id=c.customer_id 
join branches b on a.branch_id=b.branch_id 
limit 25;

-- Find customers without recorded loans
select c.customer_id,c.first_name,c.last_name from customers c 
left join loans l on c.customer_id=l.customer_id 
where l.loan_id is null;

-- SUBQUERIES
-- Find accounts with above-average balances
select account_id,customer_id,balance from accounts 
where balance>(select avg(balance) from accounts) 
order by balance desc;

-- Find customers with loans greater than ₹1 million 
select customer_id,first_name,last_name from customers 
where customer_id in (select customer_id from loans where loan_amount>1000000);

-- Rank accounts by balance across the bank 
select account_id,customer_id,balance,
rank() over(order by balance desc) as balance_rank from accounts;

-- Rank accounts within each branch
select account_id,customer_id,branch_id,balance,
dense_rank() over(partition by branch_id  order by balance desc) as branch_rank from accounts;

-- Number transactions chronologically for each account 
select transaction_id,account_id,transaction_date,amount,
row_number() over(partition by account_id order by transaction_date,transaction_id) as transaction_number from transactions;

